def recover_note_objects(code):
 notes=[]
 for node in ast.walk(ast.parse(code)):
  if isinstance(node,ast.Dict):
   keys=[]
   for k in node.keys:
    try:keys.append(ast.literal_eval(k))
    except Exception:keys.append(None)
   if 'key' in keys and 'note' in keys and 'incomplete' in keys:
    obj={}
    for k,v in zip(keys,node.values):
     try:obj[k]=ast.literal_eval(v)
     except Exception:
      if k=='note':
       # Concatenations involving a shared caution can be evaluated with shared=''.
       try:obj[k]=eval(compile(ast.Expression(v),'<notes>','eval'),{'shared':'','common':''})
       except Exception:obj[k]=ast.unparse(v)
      elif k=='sources':obj[k]=[]
    notes.append(obj)
 return notes
